from abc import ABC, abstractmethod

class Vehicle(ABC):
    @abstractmethod
    def start_engine(self):
        pass

class Car(Vehicle):
    def start_engine(self):
        return 'Car engine started'

if __name__ == '__main__':
    # 抽象类不可实例化，此处演示异常捕获
    try:
        v = Vehicle()
    except TypeError:
        print('Cannot instantiate abstract class')

    # 子类可正常实例化并调用方法
    car = Car()
    print(car.start_engine())
